#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=11

banner "OCI setup for the read-aloud app"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tenancy and home region"
say "Sign in to the OCI Console with the account that holds the \$500 hackathon credits."
open_url "https://cloud.oracle.com/"
step "Top-right Profile icon → Tenancy: <name> → copy the OCID."
ask OCI_TENANCY_OCID "Paste the tenancy OCID (ocid1.tenancy…):"
step "Top bar region picker → note the region identifier, e.g. us-chicago-1 or us-ashburn-1."
ask OCI_REGION "Home region identifier:"
write_env OCI_TENANCY_OCID "$OCI_TENANCY_OCID"
write_env OCI_REGION "$OCI_REGION"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Compartment"
say "Everything for the hackathon lives in one compartment so it's easy to find and delete."
open_url "https://cloud.oracle.com/identity/compartments"
step "Create Compartment → Name: hacktn26 → Parent: root → Create."
step "Open it and copy its OCID."
ask OCI_COMPARTMENT_OCID "Paste the compartment OCID (ocid1.compartment…):"
write_env OCI_COMPARTMENT_OCID "$OCI_COMPARTMENT_OCID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "API signing key (lets the app call OCI)"
step "Profile icon → My profile → API keys (under Resources) → Add API key."
step "Choose 'Generate API key pair' → Download private key → Add."
step "The 'Configuration file preview' shows user, fingerprint, tenancy, region. Keep it open."
ask OCI_USER_OCID "Paste the user OCID (ocid1.user…):"
ask OCI_FINGERPRINT "Paste the fingerprint (aa:bb:…):"
ask OCI_PRIVATE_KEY_PATH "Full path where you saved the downloaded .pem:"
if [[ ! -f "$OCI_PRIVATE_KEY_PATH" ]]; then warn "No file at $OCI_PRIVATE_KEY_PATH yet; fix the path before running the app."; fi
note "Never commit the .pem. Share it with teammates over a private channel."
write_env OCI_USER_OCID "$OCI_USER_OCID"
write_env OCI_FINGERPRINT "$OCI_FINGERPRINT"
write_env OCI_PRIVATE_KEY_PATH "$OCI_PRIVATE_KEY_PATH"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Generative AI model and Speech region"
say "OCI Generative AI only runs in some regions; us-chicago-1 is the usual one."
step "Region picker → switch to a region that lists Analytics & AI → Generative AI (subscribe to it if asked)."
step "Generative AI → Playground → Chat → pick a model that writes well (e.g. a Llama, Cohere Command, gpt-oss, or Gemini option)."
step "Click 'View code' and copy the model ID (an OCID or a model name) and the endpoint region."
ask OCI_GENAI_REGION "Generative AI region identifier:"
ask OCI_GENAI_MODEL_ID "Model ID shown in 'View code':"
step "Analytics & AI → Speech: confirm it opens in your chosen region (realtime + TTS are tested in the first-hour spike)."
ask OCI_SPEECH_REGION "Region to use for Speech (Enter = same as home region if blank):"
[[ -z "$OCI_SPEECH_REGION" ]] && OCI_SPEECH_REGION="$OCI_REGION"
write_env OCI_GENAI_REGION "$OCI_GENAI_REGION"
write_env OCI_GENAI_MODEL_ID "$OCI_GENAI_MODEL_ID"
write_env OCI_SPEECH_REGION "$OCI_SPEECH_REGION"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Hackathon Starter Kit (network, VM, MySQL)"
say "Trial tenancies can't create new resources, so we reuse the hackathon Starter Kit (ADR-0010)."
say "It gives a VCN (mysql_vcn) with 22/80/443 open, an Oracle Linux VM, and MySQL HeatWave in a private subnet."
open_url "https://cloud.oracle.com/resourcemanager/stacks"
step "Compartment = root. If no oci-hackathon-starterkit stack exists, deploy it from github.com/lefred/oci-hackathon-starterkit (Deploy to Oracle Cloud)."
step "Open the stack → Jobs → the Apply job → Outputs. Note webserver_public_ip and heatwave_private_ip."
pause "Press Enter once you have the outputs open."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "App VM (the kit's Webserver)"
step "Outputs → ssh_private_key → Show → copy it all, then on this machine:"
note "  pbpaste > ~/.ssh/tolk_vm && chmod 600 ~/.ssh/tolk_vm"
note "  ssh -i ~/.ssh/tolk_vm opc@<webserver_public_ip>   (user is opc on Oracle Linux)"
ask VM_PUBLIC_IP "webserver_public_ip:"
ask VM_SSH_KEY_PATH "Path to the SSH private key for this VM:"
APP_DOMAIN="${VM_PUBLIC_IP//./-}.sslip.io"
say "Your HTTPS address will be: https://$APP_DOMAIN"
write_env VM_PUBLIC_IP "$VM_PUBLIC_IP"
write_env VM_SSH_KEY_PATH "$VM_SSH_KEY_PATH"
write_env APP_DOMAIN "$APP_DOMAIN"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "MySQL HeatWave: a database and user for the app"
say "The kit's admin login is its public default (admin / MyPassw0rd!). Give the app its own user, then change the admin password."
step "On the VM: mysqlsh admin@<heatwave_private_ip> --sql   (password MyPassw0rd!)"
note "  CREATE DATABASE tolk;"
note "  CREATE USER 'tolk'@'%' IDENTIFIED BY '<app password>';"
note "  GRANT ALL PRIVILEGES ON tolk.* TO 'tolk'@'%';"
note "  ALTER USER 'admin'@'%' IDENTIFIED BY '<new admin password>';"
note "Use letters, digits and _ in passwords: they go inside a URL."
ask MYSQL_HOST "heatwave_private_ip:"
ask_secret MYSQL_APP_PASSWORD "Password you set for user tolk:"
DATABASE_URL="mysql://tolk:${MYSQL_APP_PASSWORD}@${MYSQL_HOST}:3306/tolk"
write_env DATABASE_URL "$DATABASE_URL"
note "Laptops can't reach the private subnet. Local dev uses LOCAL_DATABASE_URL (MySQL container, npm run db:up)."
write_env LOCAL_DATABASE_URL "mysql://tolk:tolk@localhost:3306/tolk"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Container Registry (OCIR)"
step "Profile → Tenancy → copy 'Object storage namespace'."
ask OCIR_NAMESPACE "Tenancy namespace:"
step "Registry host is <region-key>.ocir.io, e.g. ord.ocir.io for Chicago, iad.ocir.io for Ashburn."
ask OCIR_HOST "Registry host:"
step "Profile → My profile → Auth tokens → Generate token → copy it (shown once)."
ask_secret OCIR_AUTH_TOKEN "Auth token:"
ask OCIR_USERNAME "Login username: <namespace>/<your OCI username or email> (identity-domain tenancies may need <namespace>/<domain>/<username>):"
write_env OCIR_NAMESPACE "$OCIR_NAMESPACE"
write_env OCIR_HOST "$OCIR_HOST"
write_env OCIR_USERNAME "$OCIR_USERNAME"
write_env OCIR_AUTH_TOKEN "$OCIR_AUTH_TOKEN"
write_env APP_IMAGE "${OCIR_HOST}/${OCIR_NAMESPACE}/hacktn26/app:latest"
if command -v docker >/dev/null 2>&1 && confirm "Test 'docker login $OCIR_HOST' now?"; then
  printf '%s' "$OCIR_AUTH_TOKEN" | docker login "$OCIR_HOST" -u "$OCIR_USERNAME" --password-stdin || warn "Login failed: check the username format above."
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Better Auth"
BETTER_AUTH_SECRET="$(_existing BETTER_AUTH_SECRET || true)"
if [[ -z "$BETTER_AUTH_SECRET" ]]; then BETTER_AUTH_SECRET="$(openssl rand -base64 32)"; fi
say "Generated a session secret and set the public URL."
write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
write_env BETTER_AUTH_URL "https://$APP_DOMAIN"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Prepare the VM (Docker + firewall)"
say "Oracle Linux runs firewalld, which blocks 80/443 even after the security list allows them."
say "scripts/provision-vm.sh installs Docker, opens 80/443 in firewalld, and copies the env + key files."
if confirm "Run scripts/provision-vm.sh against $VM_PUBLIC_IP now?"; then
  bash "$(dirname "$0")/provision-vm.sh" || warn "Provisioning failed; re-run scripts/provision-vm.sh after fixing."
else
  SKIPPED+=("Run scripts/provision-vm.sh")
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "GitHub deploy secrets"
say "The deploy workflow SSHes into the VM and runs docker compose pull + up."
set_secret DEPLOY_HOST "$VM_PUBLIC_IP"
set_secret DEPLOY_USER "opc"
if [[ -f "$VM_SSH_KEY_PATH" ]]; then set_secret DEPLOY_SSH_KEY "$(cat "$VM_SSH_KEY_PATH")"; else SKIPPED+=("GitHub secret DEPLOY_SSH_KEY (key file not found)"); fi
set_secret OCIR_USERNAME "$OCIR_USERNAME"
set_secret OCIR_AUTH_TOKEN "$OCIR_AUTH_TOKEN"
set_var OCIR_HOST "$OCIR_HOST"
set_var APP_IMAGE "${OCIR_HOST}/${OCIR_NAMESPACE}/hacktn26/app:latest"

finish
say "Next: open https://$APP_DOMAIN on a phone and allow the microphone."
